mapper.select:
SELECT r.resident_id, r.name, r.phone, r.id_card, r.gender, r.avatar_url, GROUP_CONCAT(DISTINCT CONCAT(b.building_name, '-', h.unit_no, '单元-', h.house_number) SEPARATOR ', ') AS house_name, COUNT(DISTINCT hra.house_id) AS house_count, r.type, r.register_way, r.status, r.create_time FROM resident r LEFT JOIN house_resident_auth hra ON r.resident_id = hra.resident_id LEFT JOIN house h ON hra.house_id = h.house_id LEFT JOIN building b ON h.building_id = b.building_id
AND r.type = #{query.type}
AND r.name LIKE CONCAT('%', #{query.name}, '%')
AND (r.name LIKE CONCAT('%', #{query.keyword}, '%') OR r.phone LIKE CONCAT('%', #{query.keyword}, '%') OR r.id_card LIKE CONCAT('%', #{query.keyword}, '%'))
AND r.gender = #{query.gender}
AND r.register_way = #{query.registerWay}
AND r.status = #{query.status}
AND h.building_id = #{query.buildingId}
AND h.unit_no = #{query.unitNo}
AND h.house_number = #{query.houseNumber}
GROUP BY r.resident_id ORDER BY r.resident_id ASC

mapper.update:
UPDATE resident
name = #{name}, phone = #{phone}, password = #{password}, id_card = #{idCard}, gender = #{gender}, type = #{type}, register_way = #{registerWay}, avatar_url = #{avatarUrl}, status = #{status},
WHERE resident_id = #{residentId}
